<header class="admin-page-head"><div><a href="/admin">← Dashboard</a><h1><?= e($enquiry['reference']) ?></h1></div><span class="status-badge"><?= e($enquiry['status']) ?></span></header><div class="admin-detail-grid"><section class="admin-panel"><h2>Customer</h2><dl class="admin-dl"><div><dt>Name</dt><dd><?= e($enquiry['customer_name']) ?></dd></div><div><dt>Phone</dt><dd><?= e($enquiry['customer_phone']) ?></dd></div><div><dt>Email</dt><dd><?= e($enquiry['customer_email']?:'—') ?></dd></div><div><dt>Requested</dt><dd><?= e($enquiry['requested_date']) ?> <?= e($enquiry['requested_time']) ?></dd></div><div><dt>Fulfilment</dt><dd><?= e(ucfirst($enquiry['fulfilment_method'])) ?></dd></div><div><dt>Address</dt><dd><?= nl2br(e($enquiry['delivery_address']?:'—')) ?></dd></div></dl></section><section class="admin-panel"><h2>Selection snapshot</h2><?php if($enquiry['bouquet_snapshot']): ?><pre><?= e(json_encode(json_decode($enquiry['bouquet_snapshot'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre><?php endif; ?><?php if($enquiry['cafe_snapshot']): ?><pre><?= e(json_encode(json_decode($enquiry['cafe_snapshot'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre><?php endif; ?></section><form class="admin-panel" method="post" action="/admin/enquiries/<?= (int)$enquiry['id'] ?>/status"><?= csrf_field() ?><h2>Update status</h2><label class="field"><span>Status</span><select name="status"><?php foreach($statuses as $status): ?><option <?= $status===$enquiry['status']?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select></label><label class="field"><span>Internal note</span><textarea name="note"></textarea></label><button class="button button-block" type="submit">Update status</button></form></div>

